// ═══ RECORD: one line replaces 50+ lines of POJO boilerplate ═══
record Trade(String tradeId, String symbol, BigDecimal amount, String status) {
    // Auto-generated: constructor, tradeId(), symbol(), amount(), status(),
    //                 equals(), hashCode(), toString()

    // Custom compact constructor for validation:
    Trade {
        if (tradeId == null || tradeId.isBlank()) throw new IllegalArgumentException("tradeId required");
        if (amount.signum() < 0) throw new IllegalArgumentException("amount cannot be negative");
    }

    // Custom method:
    boolean isSettled() { return "SETTLED".equals(status); }

    // Static factory:
    static Trade fromCsv(String csv) {
        String[] parts = csv.split(",");
        return new Trade(parts[0], parts[1], new BigDecimal(parts[2]), parts[3]);
    }
}

// ═══ USAGE ═══
Trade t1 = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED");
String id = t1.tradeId();           // accessor (NOT getTradeId!)
BigDecimal amt = t1.amount();       // accessor
boolean eq = t1.equals(new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"), "SETTLED")); // true!
String str = t1.toString();         // "Trade[tradeId=TRD-001, symbol=RELIANCE, amount=245050, status=SETTLED]"

// ═══ RECORDS ARE IDEAL FOR ═══
record ValidationResult(boolean valid, List<String> errors) {}       // DTO
record AccountBalance(String accountId, BigDecimal balance) {}        // Value object
record TradeKey(String symbol, String side) {}                        // Map key (equals/hashCode!)
record Range(BigDecimal min, BigDecimal max) {}                       // Tuple

// ═══ RECORDS CANNOT ═══
// ❌ record Trade(...) extends BaseEntity {}  // cannot extend classes
// ❌ instance fields: private String extra;    // only component fields
// ❌ mutable: t1.setAmount(...)               // no setters (immutable)
// ✅ CAN: implement interfaces, have static fields/methods, have instance methods
