@Test void autoEqualsBasedOnAllComponents() {
    record Point(int x, int y) {}
    assertThat(new Point(1, 2)).isEqualTo(new Point(1, 2));       // equal!
    assertThat(new Point(1, 2)).isNotEqualTo(new Point(1, 3));    // different y
}

@Test void autoHashCodeConsistent() {
    record Point(int x, int y) {}
    assertThat(new Point(1, 2).hashCode()).isEqualTo(new Point(1, 2).hashCode());
}

@Test void autoToString() {
    record Trade(String id, int qty) {}
    assertThat(new Trade("T1", 100).toString()).isEqualTo("Trade[id=T1, qty=100]");
}

@Test void accessorsUseComponentNames() {
    record Trade(String id, int qty) {}
    Trade t = new Trade("T1", 100);
    assertThat(t.id()).isEqualTo("T1");    // NOT getId()!
    assertThat(t.qty()).isEqualTo(100);    // NOT getQty()!
}

@Test void compactConstructorValidates() {
    record Amount(BigDecimal value) {
        Amount { if (value.signum() < 0) throw new IllegalArgumentException("negative!"); }
    }
    assertThatThrownBy(() -> new Amount(new BigDecimal("-1")))
        .isInstanceOf(IllegalArgumentException.class);
}

@Test void recordsAreImmutable() {
    record Trade(String id) {}
    Trade t = new Trade("T1");
    // t.id = "T2";  // COMPILE ERROR — no setter, field is final!
}

@Test void recordsWorkAsMapKeys() {
    record Key(String symbol, String side) {}
    Map<Key, Integer> map = Map.of(new Key("RELIANCE", "BUY"), 100, new Key("TCS", "SELL"), 50);
    assertThat(map.get(new Key("RELIANCE", "BUY"))).isEqualTo(100);  // equals/hashCode work!
}
