package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

class RecordsTest {

    record TransferRequest(String from, String to, BigDecimal amount) {
        TransferRequest {                                // compact constructor validates
            if (amount.signum() <= 0) throw new IllegalArgumentException("amount <= 0");
        }
    }

    @Test
    void recordIsImmutableWithValueEquality() {
        var a = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000"));
        var b = new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000"));

        assertThat(a).isEqualTo(b);                      // value-based equals
        assertThat(a.amount()).isEqualByComparingTo("50000");
        assertThatThrownBy(() -> new TransferRequest("X", "Y", BigDecimal.ZERO))
            .isInstanceOf(IllegalArgumentException.class);
    }
}
